SourceCode.Declaration:
/// <summary>
/// Task service class for TMS engine processing.
/// </summary>
class METTMSEngineProcessingTaskService extends METSysOperationTaskService
{
    guid topPickingProcessId;
    METTMSEngineProcessingQueue queueTmp;

}

Method.Source:
/// <summary>
///  Initializes the object.
/// </summary>
protected void initialise()
{
    METTMSEngineProcessingContract contract;

    super();

    // get the topPickingProcessId from the contract
    contract            = dataContract as METTMSEngineProcessingContract;
    topPickingProcessId = contract.parmTopPickingProcessId();
}

/// <summary>
/// Executes the main process.
/// </summary>
/// <param name = "_contract">
/// <c>METTMSEngineProcessingContract</c>.
/// </param>
public void process(METTMSEngineProcessingContract _contract)
{
    this.processInternal(_contract);

    info("@MET:TMSProcessingStatusCompleted");
}

/// <summary>
/// Runs tasks of the task service class.
/// </summary>
/// <param name = "_readPast">Table read past setting</param>
protected void processTask(boolean _readPast)
{
    while (this.getDataFromTopPickingQueue(topPickingProcessId, _readPast))
    {
        try
        {
            if (queueTmp.RecId != 0)
            {
                this.updateSyncStatus(METTMSSyncStatus::Processing);

                info(strFmt("@MET:TMSProcessingStatusInProgress", enum2Str(queueTmp.OrderType), queueTmp.DocumentNumber, enum2Str(queueTmp.ExecutionMode)));

                this.execute();
            }
        }
        catch (Exception::Error)
        {
            this.updateSyncStatus(METTMSSyncStatus::Error);
        }
    }
}

/// <summary>
/// Gets data from queue.
///</summary>
/// <param name = "_processId">Top picking guid.</param>
/// <param name = "_readPast">boolean to read past records or not</param>
/// <returns>True, if data is retrieved from the queue; otherwise; false.</returns>
private boolean getDataFromTopPickingQueue(guid _processId, boolean _readPast)
{
    #OCCRetryCount

    METTMSEngineProcessingQueue topPickingQueue;
    int                         backOffWait;

    Microsoft.Dynamics.Ax.Xpp.DeadlockException deadLockException;
    Microsoft.Dynamics.Ax.Xpp.UpdateConflictException updateConflictException;
    Microsoft.Dynamics.Ax.Xpp.TransientSqlConnectionError transientSqlConnectionError;

    topPickingQueue.readPast(_readPast);

    try
    {
        ttsbegin;

        select firstonly pessimisticlock topPickingQueue
            where topPickingQueue.ProcessId == _processId;

        if (topPickingQueue.RecId)
        {
            queueTmp.data(topPickingQueue);

            topPickingQueue.delete();
        }
        else
        {
            DictTable queueDictTable = new DictTable(tableNum(METTMSEngineProcessingQueue));
            queueTmp = queueDictTable.makeRecord();
        }

        ttscommit;
    }
    catch (deadLockException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw deadLockException;
            }
        }
        else
        {
            throw deadLockException;
        }
    }
    catch (updateConflictException)
    {
        if (appl.ttsLevel() == 0)
        {
            if (xSession::currentRetryCount() < #RetryNum)
            {
                backOffWait = RandomGenerate::construct().randomInt(100, 5000);
                sleep(xSession::currentRetryCount() * backOffWait);
                retry;
            }
            else
            {
                throw Exception::UpdateConflictNotRecovered;
            }
        }
        else
        {
            throw updateConflictException;
        }
    }
    catch (transientSqlConnectionError)
    {
        if (SysTransientSqlConnectionErrorHandler::retryTransientSqlConnectionError())
        {
            retry;
        }
        else
        {
            throw transientSqlConnectionError;
        }
    }

    return (queueTmp.RecId != 0);
}

/// <summary>
/// Executes the process.
/// </summary>
private void execute()
{
    METTMSEngineOrderProccess tmsEngineOrderProcess;
    Common common;

    ttsbegin;

    if (queueTmp.OrderType == METTMSOrderType::SalesOrder)
    {
        common = SalesTable::find(queueTmp.DocumentNumber);
    }
    else
    {
        common = InventTransferTable::find(queueTmp.DocumentNumber);
    }

    tmsEngineOrderProcess = METTMSEngineOrderProccess::construct(queueTmp.ExecutionMode, common);
    tmsEngineOrderProcess.run();

    this.updateSyncStatus(METTMSSyncStatus::Processed);

    ttscommit;
}

/// <summary>
/// Updates sync status.
/// </summary>
/// <param name = "_syncStatus"></param>
private void updateSyncStatus(METTMSSyncStatus _syncStatus)
{
    ttsbegin;

    METTMSProcessingStatus tmsProcessingStatus = METTMSProcessingStatus::find(queueTmp.OrderType, queueTmp.DocumentNumber, queueTmp.ExecutionMode, true);

    switch (_syncStatus)
    {
        case METTMSSyncStatus::Processing:
            tmsProcessingStatus.ProcessStartDateTime = DateTimeUtil::getSystemDateTime();
            tmsProcessingStatus.NoOfAttempts += 1;
            break;

        case METTMSSyncStatus::Processed, METTMSSyncStatus::Error:
            tmsProcessingStatus.ProcessEndDateTime = DateTimeUtil::getSystemDateTime();
            break;

    }

    tmsProcessingStatus.Status = _syncStatus;

    tmsProcessingStatus.update();

    ttscommit;
}

/// <summary>
/// Updates the record upon error.
/// </summary>
protected void updateOnError()
{
    this.updateSyncStatus(METTMSSyncStatus::Error);
}
